<?php
require __DIR__ . '/app/bootstrap.php'; require __DIR__ . '/app/tickets.php'; require __DIR__ . '/app/layout.php';
$user=require_permission('view_all_tickets');$from=trim((string)($_GET['from']??date('Y-m-01')));$to=trim((string)($_GET['to']??date('Y-m-d')));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from))$from=date('Y-m-01');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$to))$to=date('Y-m-d');$params=['from'=>$from.' 00:00:00','to'=>$to.' 23:59:59'];$scope=ticket_scope_sql($user,$params);$base='t.deleted_at IS NULL AND t.created_at BETWEEN :from AND :to'.$scope;
$total=(int)db()->prepare('SELECT COUNT(*) FROM tickets t WHERE '.$base)->execute($params);$q=db()->prepare('SELECT COUNT(*) FROM tickets t WHERE '.$base);$q->execute($params);$total=(int)$q->fetchColumn();$closed=db()->prepare('SELECT COUNT(*) FROM tickets t WHERE '.$base.' AND t.status="closed"');$closed->execute($params);$closed=(int)$closed->fetchColumn();$overdue=db()->prepare('SELECT COUNT(*) FROM tickets t WHERE '.$base.' AND t.status<>"closed" AND TIMESTAMPDIFF(DAY,t.created_at,NOW())>=COALESCE((SELECT open_days FROM sla_rules sr WHERE sr.priority=t.priority),7)');$overdue->execute($params);$overdue=(int)$overdue->fetchColumn();
$byDepartment=db()->prepare('SELECT d.name,COUNT(*) count,SUM(t.status="closed") closed FROM tickets t JOIN departments d ON d.id=t.department_id WHERE '.$base.' GROUP BY d.id,d.name ORDER BY count DESC');$byDepartment->execute($params);$departmentRows=$byDepartment->fetchAll();$byAssignee=db()->prepare('SELECT COALESCE(a.full_name,"Unassigned") name,COUNT(DISTINCT t.id) count FROM tickets t LEFT JOIN users a ON a.id=t.assignee_id LEFT JOIN ticket_assignees ta ON ta.ticket_id=t.id WHERE '.$base.' GROUP BY COALESCE(a.id,0),a.full_name ORDER BY count DESC');$byAssignee->execute($params);$assigneeRows=$byAssignee->fetchAll();$leave=db()->prepare('SELECT status,COUNT(*) count FROM leave_requests WHERE submitted_at BETWEEN ? AND ? GROUP BY status ORDER BY status');$leave->execute([$params['from'],$params['to']]);$leaveRows=$leave->fetchAll();
if(($_GET['format']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename="ticket-report.csv"');$out=fopen('php://output','w');fputcsv($out,['Metric','Value']);fputcsv($out,['Tickets created',$total]);fputcsv($out,['Closed',$closed]);fputcsv($out,['Overdue',$overdue]);fputcsv($out,[]);fputcsv($out,['Department','Tickets','Closed']);foreach($departmentRows as $row)fputcsv($out,[$row['name'],$row['count'],$row['closed']]);fputcsv($out,[]);fputcsv($out,['Assignee','Tickets']);foreach($assigneeRows as $row)fputcsv($out,[$row['name'],$row['count']]);exit;}
page_start('Reports',$user);?><div class="page-head"><div><p class="eyebrow">Operations</p><h1>Reports</h1><p class="page-subtitle">Ticket workload, closure, SLA, and leave activity for the selected period.</p></div><a class="button button-secondary" href="reports.php?from=<?=e($from)?>&to=<?=e($to)?>&format=csv">Export CSV</a></div><form method="get" class="filter-panel"><div class="filter-grid"><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="button">Apply</button></div></form><section><div class="metric-grid"><div class="metric-card"><span>Created</span><strong><?=$total?></strong></div><div class="metric-card"><span>Closed</span><strong><?=$closed?></strong></div><div class="metric-card metric-card-alert"><span>Overdue</span><strong><?=$overdue?></strong></div><div class="metric-card"><span>Closure rate</span><strong><?=$total?round($closed/$total*100):0?>%</strong></div></div></section><section><h2>Workload by department</h2><div class="table-wrap"><table class="ticket-table"><thead><tr><th>Department</th><th>Tickets</th><th>Closed</th></tr></thead><tbody><?php foreach($departmentRows as $row):?><tr><td><?=e($row['name'])?></td><td><?=$row['count']?></td><td><?=$row['closed']?></td></tr><?php endforeach;?></tbody></table></div></section><section><h2>Workload by assignee</h2><div class="table-wrap"><table class="ticket-table"><thead><tr><th>Assignee</th><th>Tickets</th></tr></thead><tbody><?php foreach($assigneeRows as $row):?><tr><td><?=e($row['name'])?></td><td><?=$row['count']?></td></tr><?php endforeach;?></tbody></table></div></section><section><h2>Leave activity</h2><div class="table-wrap"><table class="ticket-table"><thead><tr><th>Status</th><th>Requests</th></tr></thead><tbody><?php foreach($leaveRows as $row):?><tr><td><?=e($row['status'])?></td><td><?=$row['count']?></td></tr><?php endforeach;?></tbody></table></div></section><?php page_end();
